//! Pre-computed fixed Huffman tables for DEFLATE block type 1.
//!
//! This module provides compile-time constant lookup tables for the DEFLATE
//! "fixed" block type (block type 1), as defined in RFC 1951 Section 3.2.6.
//! When the deflate encoder chooses fixed Huffman codes instead of dynamic
//! codes, the inflate decoder uses these pre-computed tables to avoid runtime
//! table construction.
//!
//! The tables were originally generated by the `makefixed()` function in C zlib
//! and stored in `inffixed.h`. They are equivalent to calling `inflate_table()`
//! with the fixed code lengths specified by the DEFLATE standard.
//!
//! # `op` field encoding
//!
//! Each [`Code`] entry's `op` field uses the encoding defined by
//! `inflate_table()`:
//!
//! | Bit pattern   | Decimal | Meaning                                              |
//! |---------------|---------|------------------------------------------------------|
//! | `0000_0000`   | 0       | Literal byte — `val` is the byte value               |
//! | `0000_tttt`   | 1–15    | Sub-table link — `tttt` is the number of index bits  |
//! | `0001_eeee`   | 16–31   | Length or distance — `eeee` extra bits, `val` = base |
//! | `0100_0000`   | 64      | Invalid code marker                                  |
//! | `0110_0000`   | 96      | End-of-block marker (32 + 64)                        |

use super::state::{CodeTableRef, InflateState};
use super::table::Code;

// ---------------------------------------------------------------------------
// Helper — short alias for `Code::new` to keep table lines within 100 columns
// ---------------------------------------------------------------------------

/// Shorthand constructor for [`Code`] values used in const table initializers.
///
/// Equivalent to `Code::new(op, bits, val)` but reduces line length when
/// constructing the 512-entry `LENFIX` and 32-entry `DISTFIX` tables.
#[allow(non_snake_case)]
const fn C(op: u8, bits: u8, val: u16) -> Code {
    Code::new(op, bits, val)
}

// ---------------------------------------------------------------------------
// LENFIX — Fixed length/literal code table (512 entries, 9-bit root)
// ---------------------------------------------------------------------------

/// Pre-computed fixed Huffman table for length/literal codes.
///
/// Contains 512 entries indexed by 9 bits of input (the root table size for
/// fixed literal/length codes). Generated by `makefixed()` — equivalent to
/// `inflate_table(LENS, ...)` with the fixed literal/length code lengths
/// defined in RFC 1951 Section 3.2.6:
///
/// - Codes 0–143:   8-bit codes (literals 0–143)
/// - Codes 144–255: 9-bit codes (literals 144–255)
/// - Codes 256–279: 7-bit codes (end-of-block + lengths)
/// - Codes 280–287: 8-bit codes (lengths)
///
/// The table encodes these into lookup entries where:
/// - `op = 0`: literal byte, `val` is the byte value
/// - `op = 96`: end-of-block (code 256)
/// - `op = 16..31`: length code, `op & 15` extra bits, `val` is base length
/// - `op = 64`: invalid code
