// ---------------------------------------------------------------------------
// inflate_fixed — configure state for fixed Huffman block decoding
// ---------------------------------------------------------------------------

/// Set the inflate state to use the pre-computed fixed Huffman code tables.
///
/// Called when a fixed block (DEFLATE block type 1) is encountered during
/// decompression. This function configures the inflate state's code table
/// references to point to the compile-time constant [`LENFIX`] and
/// [`DISTFIX`] tables, and sets the corresponding root table bit counts.
///
/// Ports the C `inflate_fixed()` function from `inftrees.c` line 64, which
/// is invoked from `inflate.c` line 727 in the `TYPEDO` state when the
/// block type field equals 1.
///
/// After this call:
/// - `state.lencode` references `LENFIX` (512 entries)
/// - `state.lenbits` = 9 (9-bit root table for length/literal codes)
/// - `state.distcode` references `DISTFIX` (32 entries)
/// - `state.distbits` = 5 (5-bit root table for distance codes)
pub(crate) fn inflate_fixed(state: &mut InflateState) {
    state.lencode = CodeTableRef::Fixed(&LENFIX);
    state.lenbits = 9;
    state.distcode = CodeTableRef::Fixed(&DISTFIX);
    state.distbits = 5;
}

// ---------------------------------------------------------------------------
// Compile-time spot-check assertions
// ---------------------------------------------------------------------------

// Verify a selection of entries match the canonical inffixed.h values.
// These are evaluated at compile time and produce zero runtime cost.

// LENFIX[0] = {96, 7, 0} — end-of-block
const _: () = assert!(LENFIX[0].op == 96 && LENFIX[0].bits == 7 && LENFIX[0].val == 0);
// LENFIX[1] = {0, 8, 80} — literal 80
const _: () = assert!(LENFIX[1].op == 0 && LENFIX[1].bits == 8 && LENFIX[1].val == 80);
// LENFIX[255] = {0, 9, 254} — literal 254 (9-bit code)
const _: () = assert!(LENFIX[255].op == 0 && LENFIX[255].bits == 9 && LENFIX[255].val == 254);
// LENFIX[511] = {0, 9, 255} — literal 255 (last entry)
const _: () = assert!(LENFIX[511].op == 0 && LENFIX[511].bits == 9 && LENFIX[511].val == 255);
// DISTFIX[0] = {16, 5, 1} — distance 1
const _: () = assert!(DISTFIX[0].op == 16 && DISTFIX[0].bits == 5 && DISTFIX[0].val == 1);
// DISTFIX[15] = {64, 5, 0} — invalid code
const _: () = assert!(DISTFIX[15].op == 64 && DISTFIX[15].bits == 5 && DISTFIX[15].val == 0);
// DISTFIX[31] = {64, 5, 0} — invalid code (last entry)
const _: () = assert!(DISTFIX[31].op == 64 && DISTFIX[31].bits == 5 && DISTFIX[31].val == 0);

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::super::state::{CodeTableRef, InflateState};
    use super::*;

    #[test]
    fn lenfix_has_512_entries() {
        assert_eq!(LENFIX.len(), 512);
    }

    #[test]
    fn distfix_has_32_entries() {
        assert_eq!(DISTFIX.len(), 32);
    }

    #[test]
    fn lenfix_spot_checks() {
        // LENFIX[0] = end-of-block
        assert_eq!((LENFIX[0].op, LENFIX[0].bits, LENFIX[0].val), (96, 7, 0));
        // LENFIX[1] = literal 80
        assert_eq!((LENFIX[1].op, LENFIX[1].bits, LENFIX[1].val), (0, 8, 80));
        // LENFIX[128] = second-half end-of-block
        assert_eq!(
            (LENFIX[128].op, LENFIX[128].bits, LENFIX[128].val),
            (96, 7, 0)
        );
        // LENFIX[255] = literal 254 (9-bit)
        assert_eq!(
            (LENFIX[255].op, LENFIX[255].bits, LENFIX[255].val),
            (0, 9, 254)
        );
        // LENFIX[511] = literal 255 (last)
        assert_eq!(
            (LENFIX[511].op, LENFIX[511].bits, LENFIX[511].val),
            (0, 9, 255)
        );
    }

    #[test]
    fn distfix_spot_checks() {
        // DISTFIX[0] = distance 1
        assert_eq!((DISTFIX[0].op, DISTFIX[0].bits, DISTFIX[0].val), (16, 5, 1));
        // DISTFIX[15] = invalid
        assert_eq!(
            (DISTFIX[15].op, DISTFIX[15].bits, DISTFIX[15].val),
            (64, 5, 0)
        );
        // DISTFIX[23] = distance 24577 (largest)
        assert_eq!(
            (DISTFIX[23].op, DISTFIX[23].bits, DISTFIX[23].val),
            (29, 5, 24577)
        );
        // DISTFIX[31] = invalid (last)
        assert_eq!(
            (DISTFIX[31].op, DISTFIX[31].bits, DISTFIX[31].val),
            (64, 5, 0)
        );
    }

    #[test]
    fn inflate_fixed_sets_state_correctly() {
        let mut state = InflateState::new();
        inflate_fixed(&mut state);

        assert_eq!(state.lenbits, 9);
        assert_eq!(state.distbits, 5);

        match state.lencode {
            CodeTableRef::Fixed(table) => {
                assert_eq!(table.len(), 512);
                assert_eq!(table[0].op, 96);
            }
            CodeTableRef::Dynamic(_) => panic!("Expected Fixed lencode"),
        }

        match state.distcode {
            CodeTableRef::Fixed(table) => {
                assert_eq!(table.len(), 32);
                assert_eq!(table[0].op, 16);
            }
            CodeTableRef::Dynamic(_) => panic!("Expected Fixed distcode"),
        }
    }

    #[test]
    fn inflate_fixed_enables_len_code_lookup() {
        let mut state = InflateState::new();
        inflate_fixed(&mut state);

        let code = state.len_code(0);
        assert_eq!((code.op, code.bits, code.val), (96, 7, 0));

        let code = state.len_code(1);
        assert_eq!((code.op, code.bits, code.val), (0, 8, 80));
    }

    #[test]
    fn inflate_fixed_enables_dist_code_lookup() {
        let mut state = InflateState::new();
        inflate_fixed(&mut state);

        let code = state.dist_code(0);
        assert_eq!((code.op, code.bits, code.val), (16, 5, 1));
    }

    #[test]
    fn lenfix_bits_values_are_valid() {
        for (i, code) in LENFIX.iter().enumerate() {
            assert!(
                code.bits == 7 || code.bits == 8 || code.bits == 9,
                "LENFIX[{i}].bits = {} (expected 7, 8, or 9)",
                code.bits
            );
        }
    }

    #[test]
    fn distfix_all_5_bits() {
        for (i, code) in DISTFIX.iter().enumerate() {
            assert_eq!(
                code.bits, 5,
                "DISTFIX[{i}].bits = {} (expected 5)",
                code.bits
            );
        }
    }

    #[test]
    fn lenfix_eob_count() {
        let eob_count = LENFIX.iter().filter(|c| c.op == 96).count();
        assert_eq!(eob_count, 4, "Expected 4 end-of-block markers");
        assert_eq!(LENFIX[0].op, 96);
        assert_eq!(LENFIX[128].op, 96);
        assert_eq!(LENFIX[256].op, 96);
        assert_eq!(LENFIX[384].op, 96);
    }

    #[test]
    fn lenfix_invalid_code_count() {
        let count = LENFIX.iter().filter(|c| c.op == 64).count();
        assert_eq!(count, 4, "Expected 4 invalid code markers in LENFIX");
    }

    #[test]
    fn distfix_invalid_code_count() {
        let count = DISTFIX.iter().filter(|c| c.op == 64).count();
        assert_eq!(count, 2, "Expected 2 invalid code markers in DISTFIX");
    }
}
